@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap');

:root {
  --bg-color: #0d1117;
  --bg-surface: rgba(22, 27, 34, 0.6);
  --bg-surface-solid: #161b22;
  --bg-hover: rgba(48, 54, 61, 0.5);
  --bg-active: rgba(48, 54, 61, 0.8);
  --border-color: #30363d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent-blue: #475F91;
  --accent-cyan: #00f2fe;
  --accent-green: #3fb950;

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, monospace;

  --sidebar-width: 260px;
  --header-height: 64px;
}

[data-theme="light"] {
  --bg-color: #ffffff;
  --bg-surface: rgba(246, 248, 250, 0.6);
  --bg-surface-solid: #f6f8fa;
  --bg-hover: rgba(234, 238, 242, 0.5);
  --bg-active: rgba(234, 238, 242, 0.8);
  --border-color: #d0d7de;
  --text-primary: #1f2328;
  --text-secondary: #656d76;
  --text-muted: #8c959f;
  --accent-cyan: #005cc5;
  --accent-green: #1a7f37;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  transition: background-color 0.3s ease, color 0.3s ease;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  color: var(--accent-cyan);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover {
  color: var(--text-primary);
}

h1, h2, h3, h4, h5, h6 {
  color: var(--text-primary);
  font-weight: 600;
  line-height: 1.2;
}

h1 { font-size: 2.5rem; margin-bottom: 1rem; letter-spacing: -0.02em; }
h2 { font-size: 1.75rem; margin-bottom: 1rem; margin-top: 2.5rem; }
h3 { font-size: 1.25rem; margin-bottom: 0.75rem; margin-top: 2rem; }
p { margin-bottom: 1.25rem; color: var(--text-secondary); }

/* Layout */
.app-container {
  display: flex;
  flex: 1;
  padding-top: var(--header-height);
}

.main-content {
  flex: 1;
  padding: 3rem 2rem;
  max-width: 900px;
  margin: 0 auto;
  width: 100%;
}

.main-content.wide {
  max-width: 1200px;
}

/* Header */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: rgba(13, 17, 23, 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1.5rem;
  z-index: 50;
}

[data-theme="light"] .header {
  background: rgba(255, 255, 255, 0.8);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.logo {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  text-decoration: none;
}

.logo svg {
  width: 24px;
  height: 24px;
  color: var(--accent-cyan);
}

.top-nav {
  display: none;
  align-items: center;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .top-nav { display: flex; }
}

.top-nav a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
}

.top-nav a:hover, .top-nav a.active {
  color: var(--text-primary);
}

.header-right {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.btn-icon {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 0.5rem;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}

.btn-icon:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.search-bar {
  display: none;
  align-items: center;
  gap: 0.5rem;
  background: var(--bg-surface-solid);
  border: 1px solid var(--border-color);
  padding: 0.4rem 0.8rem;
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 0.875rem;
  cursor: text;
}
@media (min-width: 768px) { .search-bar { display: flex; } }

.mobile-menu-btn {
  display: block;
}
@media (min-width: 768px) { .mobile-menu-btn { display: none; } }

/* Sidebar */
.sidebar {
  width: var(--sidebar-width);
  border-right: 1px solid var(--border-color);
  position: fixed;
  top: var(--header-height);
  bottom: 0;
  left: 0;
  background: var(--bg-color);
  overflow-y: auto;
  transition: transform 0.3s ease, width 0.3s ease;
  z-index: 40;
}

.sidebar.collapsed {
  transform: translateX(-100%);
}

@media (max-width: 1023px) {
  .sidebar {
    transform: translateX(-100%);
  }
  .sidebar.open {
    transform: translateX(0);
  }
}

.sidebar-nav {
  padding: 1.5rem 1rem;
}

.sidebar-nav-group {
  margin-bottom: 1.5rem;
}

.sidebar-nav-title {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  font-weight: 600;
  margin-bottom: 0.5rem;
  padding: 0 0.75rem;
}

.sidebar-nav a {
  display: block;
  padding: 0.4rem 0.75rem;
  color: var(--text-secondary);
  text-decoration: none;
  border-radius: 6px;
  font-size: 0.9rem;
  transition: all 0.2s;
}

.sidebar-nav a:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.sidebar-nav a.active {
  background: var(--bg-active);
  color: var(--text-primary);
  font-weight: 500;
}

.sidebar-toggle-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem;
  color: var(--text-secondary);
  font-size: 0.875rem;
  background: transparent;
  border: none;
  border-top: 1px solid var(--border-color);
  width: 100%;
  cursor: pointer;
  transition: color 0.2s;
}

.sidebar-toggle-btn:hover {
  color: var(--text-primary);
}

.app-container.has-sidebar .main-content {
  margin-left: var(--sidebar-width);
}
@media (max-width: 1023px) {
  .app-container.has-sidebar .main-content { margin-left: 0; }
}

.app-container.has-sidebar.sidebar-collapsed .main-content {
  margin-left: 0;
}

/* UI Components */
.cta-button {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--text-primary);
  color: var(--bg-color);
  padding: 0.6rem 1.2rem;
  border-radius: 6px;
  font-weight: 600;
  font-size: 0.9rem;
  border: 1px solid transparent;
  transition: transform 0.2s, box-shadow 0.2s, background 0.2s;
}

.cta-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(0, 242, 254, 0.2);
  color: var(--bg-color);
}

.cta-button.secondary {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-primary);
}
.cta-button.secondary:hover {
  background: var(--bg-hover);
  box-shadow: none;
}

.glass-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  transition: transform 0.2s, border-color 0.2s;
}

.glass-card:hover {
  border-color: var(--accent-cyan);
  transform: translateY(-2px);
}

.glass-card h3 {
  margin-top: 0;
  font-size: 1.1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.glass-card p {
  font-size: 0.9rem;
  margin-bottom: 0;
}

.glass-card a.card-link {
  display: inline-flex;
  align-items: center;
  margin-top: 1rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--accent-cyan);
}

.grid-2 { display: grid; grid-template-columns: 1fr; gap: 1.5rem; }
.grid-3 { display: grid; grid-template-columns: 1fr; gap: 1.5rem; }
@media (min-width: 640px) { .grid-2 { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 768px) { .grid-3 { grid-template-columns: repeat(3, 1fr); } }

/* Hero Section */
.hero {
  padding: 4rem 0 3rem;
  text-align: left;
}
.hero.center {
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}
.hero h1 {
  font-size: 3rem;
  margin-bottom: 1.5rem;
  background: linear-gradient(180deg, var(--text-primary) 0%, var(--text-secondary) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.hero p {
  font-size: 1.25rem;
  max-width: 600px;
  margin-bottom: 2rem;
}
.hero.center p {
  margin-left: auto;
  margin-right: auto;
}
.hero-ctas {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.hero.center .hero-ctas {
  justify-content: center;
}

/* Code & CLI Setup */
.code-block {
  background: #010409;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 0.875rem;
  margin-top: 1rem;
}

.code-header {
  display: flex;
  background: var(--bg-surface-solid);
  border-bottom: 1px solid var(--border-color);
}

.code-tab {
  padding: 0.5rem 1rem;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  border-right: 1px solid var(--border-color);
  border-bottom: 2px solid transparent;
  cursor: pointer;
  font-family: var(--font-sans);
  font-size: 0.85rem;
}

.code-tab.active {
  color: var(--text-primary);
  border-bottom-color: var(--accent-cyan);
}

.code-content {
  padding: 1rem;
  color: var(--text-primary);
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-all;
}
.code-content .command-prefix {
  color: var(--accent-green);
  user-select: none;
  margin-right: 0.5rem;
}

/* Accordion */
.accordion {
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
}
.accordion-item {
  border-bottom: 1px solid var(--border-color);
}
.accordion-item:last-child {
  border-bottom: none;
}
.accordion-header {
  padding: 1rem 1.5rem;
  background: var(--bg-surface-solid);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 500;
  user-select: none;
  transition: background 0.2s;
}
.accordion-header:hover {
  background: var(--bg-hover);
}
.accordion-content {
  padding: 0;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  background: var(--bg-color);
}
.accordion-item.active .accordion-content {
  padding: 1.5rem;
  max-height: 500px; /* arbitrary large value for transition */
}
.accordion-item.active .accordion-header {
  border-bottom: 1px solid var(--border-color);
}
.accordion-item .icon {
  transition: transform 0.3s ease;
  color: var(--text-secondary);
}
.accordion-item.active .icon {
  transform: rotate(180deg);
  color: var(--accent-cyan);
}
.step-list {
  list-style: none;
  counter-reset: steps;
}
.step-list li {
  position: relative;
  padding-left: 2rem;
  margin-bottom: 0.75rem;
  color: var(--text-secondary);
}
.step-list li::before {
  counter-increment: steps;
  content: counter(steps);
  position: absolute;
  left: 0;
  top: 0.1rem;
  width: 1.25rem;
  height: 1.25rem;
  background: var(--bg-surface-solid);
  border: 1px solid var(--border-color);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  color: var(--text-primary);
  font-weight: 600;
}

/* Badge */
.badge {
  display: inline-block;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  background: rgba(0, 242, 254, 0.1);
  color: var(--accent-cyan);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.5rem;
}

/* Footer */
.footer {
  border-top: 1px solid var(--border-color);
  padding: 4rem 2rem;
  margin-top: auto;
  background: var(--bg-color);
}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 2rem;
}
@media (min-width: 640px) {
  .footer-inner { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 1024px) {
  .footer-inner { grid-template-columns: repeat(4, 1fr); }
}
.footer-column h4 {
  font-size: 0.9rem;
  margin-bottom: 1rem;
  color: var(--text-primary);
}
.footer-column ul {
  list-style: none;
}
.footer-column ul li {
  margin-bottom: 0.5rem;
}
.footer-column ul li a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}
.footer-column ul li a:hover {
  color: var(--accent-cyan);
}

.page-section {
  margin-bottom: 5rem;
}
.page-section h2 {
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 0.5rem;
  margin-bottom: 2rem;
}

/* Mobile Nav Overlay */
.mobile-nav-overlay {
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-color);
  z-index: 45;
  display: none;
  padding: 2rem;
  flex-direction: column;
  gap: 1.5rem;
}
.mobile-nav-overlay.open {
  display: flex;
}
.mobile-nav-overlay a {
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-primary);
  text-decoration: none;
}

// App behavior
document.addEventListener('DOMContentLoaded', () => {
  // Setup theme toggle
  const themeToggle = document.getElementById('theme-toggle');
  if (themeToggle) {
    themeToggle.addEventListener('click', () => {
      const isLight = document.documentElement.getAttribute('data-theme') === 'light';
      document.documentElement.setAttribute('data-theme', isLight ? 'dark' : 'light');
      // swap icon
      themeToggle.innerHTML = isLight 
        ? '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-moon"><path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z"/></svg>'
        : '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-sun"><circle cx="12" cy="12" r="4"/><path d="M12 2v2"/><path d="M12 20v2"/><path d="m4.93 4.93 1.41 1.41"/><path d="m17.66 17.66 1.41 1.41"/><path d="M2 12h2"/><path d="M20 12h2"/><path d="m6.34 17.66-1.41 1.41"/><path d="m19.07 4.93-1.41 1.41"/></svg>';
    });
  }

  // Mobile menu
  const mobileMenuBtn = document.getElementById('mobile-menu-btn');
  const mobileNav = document.getElementById('mobile-nav');
  if (mobileMenuBtn && mobileNav) {
    mobileMenuBtn.addEventListener('click', () => {
      mobileNav.classList.toggle('open');
      const isOpen = mobileNav.classList.contains('open');
      mobileMenuBtn.innerHTML = isOpen
        ? '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>'
        : '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="4" x2="20" y1="12" y2="12"/><line x1="4" x2="20" y1="6" y2="6"/><line x1="4" x2="20" y1="18" y2="18"/></svg>';
    });
  }

  // Sidebar toggle
  const sidebarBtn = document.getElementById('sidebar-collapse-btn');
  const sidebarBtnMobile = document.getElementById('sidebar-mobile-toggle');
  const sidebar = document.getElementById('sidebar');
  const appContainer = document.querySelector('.app-container');

  if (sidebarBtn && sidebar && appContainer) {
    sidebarBtn.addEventListener('click', () => {
      sidebar.classList.toggle('collapsed');
      appContainer.classList.toggle('sidebar-collapsed');

      const isCollapsed = sidebar.classList.contains('collapsed');
      sidebarBtn.innerHTML = isCollapsed
        ? '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><path d="M9 3v18"/><path d="m14 9 3 3-3 3"/></svg> <span>Expand sidebar</span>'
        : '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><path d="M9 3v18"/><path d="m16 15-3-3 3-3"/></svg> <span>Collapse sidebar</span>';
    });
  }

  // Accordions
  const accordions = document.querySelectorAll('.accordion-item');
  accordions.forEach(acc => {
    const header = acc.querySelector('.accordion-header');
    header.addEventListener('click', () => {
      // Close others
      accordions.forEach(other => {
        if (other !== acc) {
          other.classList.remove('active');
        }
      });
      // Toggle current
      acc.classList.toggle('active');
    });
  });

  // Code Tabs
  const codeBlocks = document.querySelectorAll('.code-block');
  codeBlocks.forEach(block => {
    const tabs = block.querySelectorAll('.code-tab');
    const content = block.querySelector('.code-content code');

    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        // Remove active from all tabs in this block
        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        // Update content
        const pm = tab.getAttribute('data-pm');
        const isInit = tab.getAttribute('data-cmd') === 'init';
        const type = tab.getAttribute('data-type');

        let installCmd = '';
        if (pm === 'npm') installCmd = 'npm i -g @commerceforge/cli@latest';
        else if (pm === 'yarn') installCmd = 'yarn global add @commerceforge/cli@latest';
        else if (pm === 'pnpm') installCmd = 'pnpm add -g @commerceforge/cli@latest';

        let runCmd = '';
        if (type === 'app') runCmd = 'commerceforge app init';
        else if (type === 'theme') runCmd = 'commerceforge theme init';
        else if (type === 'hydrogen') runCmd = 'commerceforge hydrogen init';

        if (isInit) {
          content.innerHTML = `<span class="command-prefix">$</span>${runCmd}`;
        } else {
          content.innerHTML = `<span class="command-prefix">$</span>${installCmd}`;
        }
      });
    });
  });
});
